/// %v of an interface value.
pub fn iface_show(x: &Iface) -> String {
    match x.as_deref() {
        None => String::from("<nil>"),
        Some(Dyn::Box(v)) => format!("{{{} {}}}", v.w, v.h),
        Some(Dyn::Level(v)) => level_string(*v),
        Some(Dyn::Pair(v)) => format!("{{{} {}}}", v.a, v.b),
        Some(Dyn::Tag(v)) => format!("{{{}}}", v.s),
        Some(Dyn::Box2(v)) => v.to_string(),
        Some(Dyn::Bool(v)) => v.to_string(),
        Some(Dyn::Int(v)) => v.to_string(),
        Some(Dyn::Int8(v)) => v.to_string(),
        Some(Dyn::Uint(v)) => v.to_string(),
        Some(Dyn::Float32(v)) => rt::Float32(*v).to_string(),
        Some(Dyn::Float64(v)) => rt::Float(*v).to_string(),
        Some(Dyn::String(v)) => v.to_string(),
        Some(Dyn::Int32(v)) => v.to_string(),
        Some(Dyn::Outer(v)) => format!("{{{} {}}}", format!("{{{}}}", rt::Float(v.i.x)), v.n),
        Some(Dyn::Empty(v)) => String::from("{}"),
        Some(Dyn::Path(v)) => iface_slice(v, |e| e.to_string()),
        Some(Dyn::SliceInt(v)) => iface_slice(v, |e| e.to_string()),
    }
}

/// The panic of a failed x.(T) to a concrete type T.
pub fn iface_assert_fail(d: Option<&Dyn>, iface: &str, want: &str) -> ! {
    match d {
        None => panic!("gopatina-user-panic:interface conversion: {iface} is nil, not {want}"),
        Some(_) => panic!(
            "gopatina-user-panic:interface conversion: {iface} is {}, not {want}",
            iface_name(d)
        ),
    }
}

/// x.(I) to an interface type I: x, or Go's panic.
pub fn iface_assert(x: Iface, missing: fn(&Dyn) -> Option<&'static str>, want: &str) -> Iface {
    match x.as_deref() {
        None => panic!("gopatina-user-panic:interface conversion: interface is nil, not {want}"),
        Some(d) => {
            if let Some(m) = missing(d) {
                panic!(
                    "gopatina-user-panic:interface conversion: {} is not {want}: missing method {m}",
                    iface_name(Some(d))
                )
            }
        }
    }
    x
}

/// v, ok := x.(I) to an interface type I.
pub fn iface_try(x: &Iface, missing: fn(&Dyn) -> Option<&'static str>) -> (Iface, bool) {
    match x.as_deref() {
        Some(d) if missing(d).is_none() => (x.clone(), true),
        _ => (None, false),
    }
}

/// %v of a slice: its elements' %v, in brackets.
pub fn iface_slice<T>(v: &[T], show: impl Fn(&T) -> String) -> String {
    let parts: Vec<String> = v.iter().map(show).collect();
    format!("[{}]", parts.join(" "))
}

